INSERT OR IGNORE INTO offices
  (title, level, district, sort_order, county, ballot_party, seats_available, scope_kind, external_race_id, precinct_code)
SELECT DISTINCT
  'Sweetwater Precinct ' || precinct || ' ' || party_label || ' Precinct ' || position_title,
  'county', NULL, 528 + dense_rank() OVER (ORDER BY precinct, party, gender),
  'Sweetwater', party, seats, 'precinct_party_gender',
  'wy-2026-primary-sweetwater-precinct-' || lower(precinct) || '-' || lower(party) || '-' || lower(position_title),
  precinct
FROM roster;

WITH roster(precinct, precinct_name, party, party_label, gender, gender_slug, position_title, seats, candidate_name, candidate_slug, filed_at, source_page, verification_status, review_needed, review_note, candidate_source_url, seats_source_url) AS (
  SELECT
    json_extract(value, '$[0]'),
    json_extract(value, '$[1]'),
    json_extract(value, '$[2]'),
    json_extract(value, '$[3]'),
    json_extract(value, '$[4]'),
    json_extract(value, '$[5]'),
    json_extract(value, '$[6]'),
    json_extract(value, '$[7]'),
    json_extract(value, '$[8]'),
    json_extract(value, '$[9]'),
    json_extract(value, '$[10]'),
    json_extract(value, '$[11]'),
    json_extract(value, '$[12]'),
    json_extract(value, '$[13]'),
    json_extract(value, '$[14]'),
    json_extract(value, '$[15]'),
    json_extract(value, '$[16]')
