INSERT OR IGNORE INTO candidates
  (office_id, party, full_name, ballot_name, slug, state, filed_at, source_page,
   external_candidate_id, committee_gender, position_title, data_confidence,
   human_review_needed, enrichment_notes)
SELECT
  o.id, r.party, r.candidate_name, r.candidate_name, r.candidate_slug, 'WY', r.filed_at, r.source_page,
  'wy-2026-primary-' || r.candidate_slug, r.gender, r.position_title,
  CASE r.review_needed WHEN 1 THEN 'Medium' ELSE 'High' END, r.review_needed,
  TRIM('verification_status: ' || r.verification_status || '; candidate_source: ' ||
    r.candidate_source_url || '; seats_source: ' || r.seats_source_url ||
    CASE WHEN r.review_note IS NULL THEN '' ELSE '; source_note: ' || r.review_note END)
FROM roster r
JOIN offices o ON o.external_race_id =
  'wy-2026-primary-sweetwater-precinct-' || lower(r.precinct) || '-' || lower(r.party) || '-' || lower(r.position_title);
